/// Native replay implementations for fs bindings.
#[inline]
fn destack_fs_attrs_access_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    path: OsPath,
    mode: AccessMode,
) -> RuntimeResult<()> {
    let _ = (&path, &mode);

    binding.trace().run_binding_without_context(
        FS_ATTRS_ACCESS,
        binding.replay_payload_for(FS_ATTRS_ACCESS)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_fs_access(binding, path, mode)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_fs_access(binding, path, mode)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = FsAttrsAccessReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    FsAttrsAccessReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

