                            let result_recorded_item_recorded_name_os_path_utf16_kind = unsafe { value.kind.as_str()? }.to_string();
                            let result_recorded_item_recorded_name_os_path_utf16_utf16_inner_slice = unsafe { value.utf16.0.as_slice()? };
