#[inline]
fn destack_fs_watch_openat_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut resource::WatchHandle,
    directory: resource::DirectoryHandle,
    path: OsPath,
    options: WatchOptions,
) -> RuntimeResult<()> {
    let _ = (&directory, &path, &options);

    binding.trace().run_binding_without_context(
        FS_WATCH_OPENAT,
        binding.replay_payload_for(FS_WATCH_OPENAT)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_fs_watchat(binding, out, directory, path, options)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_fs_watchat(
                    binding, out, directory, path, options,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: resource::WatchHandle = unsafe { out.read() };
                let result_recorded = result_value;
                let payload = FsWatchOpenatReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    FsWatchOpenatReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    unsafe { out.write(value) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

#[inline]
fn destack_fs_xattr_fgetxattr_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeArray<u8>,
    handle: resource::FileHandle,
    name: NativeStringRef,
) -> RuntimeResult<()> {
    let _ = (&handle, &name);

    binding.trace().run_binding_without_context(
        FS_XATTR_FGETXATTR,
        binding.replay_payload_for(FS_XATTR_FGETXATTR)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_fs_fgetxattr(binding, out, handle, name)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_fs_fgetxattr(binding, out, handle, name)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: NativeArray<u8> = unsafe { out.read() };
                let result_recorded_slice = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_slice.len());
                for result_recorded_item in result_recorded_slice.iter().cloned() {
                    let result_recorded_item_recorded = result_recorded_item;
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = FsXattrFgetxattrReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    FsXattrFgetxattrReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native =
                        binding.store_array_with(value.len(), |value_native_values| {
                            for value_native_item in value {
                                let value_native_decoded = value_native_item;
                                value_native_values.push(value_native_decoded);
                            }
                            Ok(())
                        })?;
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

