/// VM replay implementations for fs bindings.
#[inline]
fn destack_fs_attrs_access_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
    path: OsPathVm,
    mode: AccessMode,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        FS_ATTRS_ACCESS,
        binding.replay_payload_for(FS_ATTRS_ACCESS)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_fs_access(binding, context, path, mode),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_fs_access(binding, context, path, mode)
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = FsAttrsAccessReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    FsAttrsAccessReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_fs_attrs_access_result(context, result)?;
    Ok(result)
}

