#[inline]
fn destack_fs_watch_openat_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
    directory: resource::DirectoryHandle,
    path: OsPathVm,
    options: WatchOptionsVm,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        FS_WATCH_OPENAT,
        binding.replay_payload_for(FS_WATCH_OPENAT)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_fs_watchat(binding, context, directory, path, options)
            }
            RuntimeWorld::Simulation => platform_simulation_vm::destack_fs_watchat(
                binding, context, directory, path, options,
            ),
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: resource::WatchHandle = value.clone();
                let result_recorded = result_value;
                let payload = FsWatchOpenatReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    FsWatchOpenatReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_fs_watch_openat_result(context, result)?;
    Ok(result)
}

